      ps.time = SIM.now - 600; ps.magic = InpMagic; ps.comment = "NQ-Q1";
      SIM.pos.push_back(ps);
      SimOrder so;
      so.ticket = 556; so.sym = "BTCUSD"; so.type = ORDER_TYPE_SELL_LIMIT; so.vol = 0.05; so.price = SIM.bid + 10.0; so.sl = SIM.bid + 600; so.tp = SIM.bid - 400;
      so.time = SIM.now - 120; so.magic = InpMagic; so.comment = "NQ-N1";
